#!/bin/bash
# Runs the app's pure-logic XCTest files without Xcode, with the XCTest stand-in (scripts/xctest-shim.swift).
# The sources named here are compiled straight into the test binary, the same way project.yml's test target does.
# CI (real XCTest) is the source of truth. Usage: scripts/run-app-tests.sh
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
out="$(mktemp -d)"
swiftc -swift-version 5 -parse-as-library -emit-module -module-name XCTest -emit-library -o "$out/libXCTest.dylib" "$root/scripts/xctest-shim.swift" \
  -Xlinker -install_name -Xlinker "$out/libXCTest.dylib" -emit-module-path "$out/XCTest.swiftmodule"
tests=("$root/NotchAppleTests/GameEngineTests.swift" "$root/NotchAppleTests/GamesMenuTests.swift" "$root/NotchAppleTests/ClaudeCodeStatusTests.swift" "$root/NotchAppleTests/GeminiFallbackTests.swift" "$root/NotchAppleTests/ClaudeUsagePaceTests.swift" "$root/NotchAppleTests/MathEngineTests.swift" "$root/NotchAppleTests/ModuleLayoutTests.swift" "$root/NotchAppleTests/TourLogicTests.swift" "$root/NotchAppleTests/ClaudeLimitsTests.swift" "$root/NotchAppleTests/TodoLogicTests.swift" "$root/NotchAppleTests/ReleaseNotesLogicTests.swift" "$root/NotchAppleTests/TennisLogicTests.swift" "$root/NotchAppleTests/UpdateCadenceLogicTests.swift" "$root/NotchAppleTests/RadarLogicTests.swift" "$root/NotchAppleTests/EntitlementLogicTests.swift" "$root/NotchAppleTests/WallpaperLogicTests.swift" "$root/NotchAppleTests/CardsLogicTests.swift" "$root/NotchAppleTests/UpdateSigningTests.swift" "$root/NotchAppleTests/PluginPinningTests.swift" "$root/NotchAppleTests/BambuPinTests.swift" "$root/NotchAppleTests/UpdateFeedTests.swift" "$root/NotchAppleTests/BambuCloudTests.swift" "$root/NotchAppleTests/BambuCameraTests.swift" "$root/NotchAppleTests/FriendsTests.swift" "$root/NotchAppleTests/CompanionStreamTests.swift" "$root/NotchAppleTests/LockCodeTests.swift" "$root/NotchAppleTests/StatusPulseTests.swift" "$root/NotchAppleTests/DoItGeometryTests.swift" "$root/NotchAppleTests/DoItPolicyTests.swift" "$root/NotchAppleTests/NotchAITests.swift" "$root/NotchAppleTests/CustomProviderTests.swift" "$root/NotchAppleTests/NotchAIConversationTests.swift" "$root/NotchAppleTests/NotchAIVoiceTests.swift" "$root/NotchAppleTests/ScreenContextTests.swift" "$root/NotchAppleTests/ResearchLogicTests.swift" "$root/NotchAppleTests/NotchAIMemoryTests.swift" "$root/NotchAppleTests/NotchAITaskTests.swift" "$root/NotchAppleTests/NotchAISkillTests.swift")
python3 "$root/scripts/gen-xctest-main.py" "${tests[@]}" > "$out/main.swift"
swiftc -swift-version 5 -I "$out" -L "$out" -lXCTest -Xlinker -rpath -Xlinker "$out" -o "$out/run" \
  "$root/NotchApple/Modules/Games/GameEngines.swift" "$root/NotchApple/Modules/Games/GamesMenuLogic.swift" "$root/NotchApple/Core/ClaudeCodeStatusLogic.swift" "$root/NotchApple/Modules/Claude/GeminiFallbackLogic.swift" "$root/NotchApple/Core/ClaudeUsageLogic.swift" "$root/NotchApple/Modules/Tools/MathEngine.swift" "$root/NotchApple/Core/ModuleLayoutLogic.swift" "$root/NotchApple/Core/TourLogic.swift" "$root/NotchApple/Core/ClaudeLimitsLogic.swift" "$root/NotchApple/Core/TodoLogic.swift" "$root/NotchApple/Core/ReleaseNotesLogic.swift" "$root/NotchApple/Modules/Tennis/TennisLogic.swift" "$root/NotchApple/Core/UpdateCadenceLogic.swift" "$root/NotchApple/Modules/Radar/RadarLogic.swift" "$root/NotchApple/Core/EntitlementLogic.swift" "$root/NotchApple/Modules/Wallpaper/WallpaperLogic.swift" "$root/NotchApple/Modules/Games/CardsLogic.swift" "$root/NotchApple/Core/UpdateSigning.swift" "$root/NotchApple/Modules/Plugins/PluginPinning.swift" "$root/NotchApple/Modules/BambuStatusChecker/BambuStatusLogic.swift" "$root/NotchApple/Modules/BambuStatusChecker/BambuCloudLogic.swift" "$root/NotchApple/Modules/BambuStatusChecker/BambuCameraLogic.swift" "$root/NotchApple/Core/UpdateFeedLogic.swift" "$root/NotchApple/Modules/Messenger/Friends/FriendsLogic.swift" "$root/NotchApple/Modules/Messenger/TicTacToeLogic.swift" "$root/NotchApple/Modules/Messenger/TwoPlayerGames.swift" "$root/NotchApple/Modules/Messenger/BoardGames.swift" "$root/NotchApple/Core/LockCodeLogic.swift" "$root/NotchApple/Core/StatusPulseLogic.swift" "$root/NotchApple/Core/DoItGeometry.swift" "$root/NotchApple/Core/DoItPolicy.swift" "$root/NotchApple/Core/CompanionMotion.swift" "$root/NotchApple/Core/NotchAIConversationLogic.swift" "$root/NotchApple/Core/NotchAIVoiceLogic.swift" "$root/NotchApple/Core/ScreenContextLogic.swift" "$root/NotchApple/Core/ResearchLogic.swift" "$root/NotchApple/Core/NotchAIMemoryLogic.swift" "$root/NotchApple/Core/NotchAISkillLogic.swift" "$root/NotchApple/Core/NotchAITaskLogic.swift" "$root/NotchApple/Core/NotchAITaskEngine.swift" "$root/NotchApple/Modules/NotchAI/Screen/ScreenOCR.swift" "$root/NotchApple/Modules/NotchAI/NotchAIGuard.swift" "$root/NotchApple/Core/OllamaDiagnosticsLogic.swift" "$root/NotchApple/Core/AppContextLogic.swift" "$root/CompanionKit/CompanionProtocol.swift" "$root/CompanionKit/CompanionPairing.swift" "$root/CompanionKit/CompanionStream.swift" "$root/scripts/xctest-ai-stubs.swift" "$root/NotchApple/Core/ModelLocality.swift" "$root/NotchApple/Modules/Claude/AIModes.swift" "$root/NotchApple/Modules/Claude/AIProviders.swift" "$root/NotchApple/Modules/Claude/AIStreaming.swift" "$root/NotchApple/Modules/Claude/ClaudeClient.swift" "$root/NotchApple/Core/KeychainHelper.swift" "$root/NotchApple/Core/LicenseKey.swift" "$root/NotchApple/Modules/Claude/AIPure.swift" "$root/NotchApple/Modules/Claude/AppleIntelligence.swift" "$root/NotchApple/Modules/Claude/GeminiFallback.swift" "${tests[@]}" "$out/main.swift"
"$out/run"
